from xml.etree.ElementTree import Element

from convert.adapters.solidworks.Archive.Construction.Metadata.ExpandXmlName import (
    ExpandXmlName,
)


# authored lexical namespaces need their own scope so autogenerated prefixes cannot shadow model names
def CheckXmlTree(
    SourceValue: Element, ParsedValue: Element, Inherited: dict[str, str]
) -> None:
    Attributes = {str(Name): Value for Name, Value in SourceValue.attrib.items()}
    Declarations = {
        Name: Value
        for Name, Value in Attributes.items()
        if Name == "xmlns" or Name.startswith("xmlns:")
    }
    ScopeValue = Inherited | {
        "" if Name == "xmlns" else Name.removeprefix("xmlns:"): Value
        for Name, Value in Declarations.items()
    }
    Expected = {
        ExpandXmlName(Name, ScopeValue, False): Value
        for Name, Value in Attributes.items()
        if Name not in Declarations
    }
    if (
        ExpandXmlName(str(SourceValue.tag), ScopeValue, True) != ParsedValue.tag
        or Expected != ParsedValue.attrib
        or (SourceValue.text or "") != (ParsedValue.text or "")
        or (SourceValue.tail or "") != (ParsedValue.tail or "")
        or len(SourceValue) != len(ParsedValue)
    ):
        raise ValueError("serialized keyword tree differs from the authored tree")
    for Source, Parsed in zip(SourceValue, ParsedValue, strict=True):
        CheckXmlTree(Source, Parsed, ScopeValue)
